class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return mid
            if nums[left] <= nums[mid]: # 为了能用有序区间的条件判断, 我们需要先确定有序区间
                if nums[left] <= target < nums[mid]:  # mid已排除
                    right = mid - 1                   # mid已排除
                else:
                    left = mid + 1                    # mid已排除
            else:
                if nums[mid] < target <= nums[right]: # mid已排除
                    left = mid + 1                    # mid已排除
                else:
                    right = mid - 1                   # mid已排除
        return -1
